const body = $json.body ?? {};
const action = String(body.action ?? '').trim();
return [{json:{
  action,
  studentId:String(body.studentId ?? '').trim(),
  targetClass:String(body.targetClass ?? '').trim(),
  reason:String(body.reason ?? '').trim(),
  note:String(body.note ?? '').trim()
}}];

let req = {};
try { req = $('تحليل طلب موقع النقل').first().json || {}; } catch(e) {}

let allStudents = [];
try { allStudents = $('البحث عن الطالب - استعلام').all().map(i => i.json || {}); } catch(e) {}

let settings = [];
try { settings = $input.all().map(i => i.json || {}).filter(r => String(r['مفتاح الفصل'] ?? '').trim()); } catch(e) {}

// 1. Check global portal lock
const portalLockRow = settings.find(r => String(r['مفتاح الفصل'] ?? '').trim() === 'PORTAL-STATUS');
const isPortalLocked = portalLockRow ? String(portalLockRow['متاح للنقل'] ?? 'نعم').trim() === 'لا' : false;

if (isPortalLocked) {
  return [{
    json: {
      success: false,
      portalLocked: true,
      message: 'سوف يُتاح الموقع قريباً لنقل الطلاب. البوابة مغلقة حالياً من قِبل إدارة المدرسة.'
    }
  }];
}

// 2. Helper for normalizing ID (Arabic numerals, symbols, spaces, leading zeros)
function normId(v) {
  if (!v) return '';
  return String(v).trim()
    .replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d))
    .replace(/[\u200B-\u200D\uFEFF]/g, '');
}

function stripId(v) {
  return normId(v).replace(/[^a-zA-Z0-9]/g, '');
}

const reqIdRaw = normId(req.studentId);
const reqIdStripped = stripId(req.studentId);
const reqIdNoZero = reqIdStripped.replace(/^0+/, '');

if (!reqIdRaw) {
  return [{ json: { success: false, message: 'يرجى إدخال رقم الطالب / الهوية الوطنية / السجل.' } }];
}

// Find student row using multi-layer flexible matching
const row = allStudents.find(r => {
  const rowIdRaw = normId(r['رقم الطالب'] ?? '');
  if (!rowIdRaw) return false;
  if (rowIdRaw === reqIdRaw) return true;

  const rowIdStripped = stripId(rowIdRaw);
  if (rowIdStripped && reqIdStripped) {
    if (rowIdStripped === reqIdStripped) return true;
    const rowIdNoZero = rowIdStripped.replace(/^0+/, '');
    if (rowIdNoZero && reqIdNoZero && rowIdNoZero === reqIdNoZero) return true;
    if (rowIdStripped.startsWith(reqIdStripped) || reqIdStripped.startsWith(rowIdStripped)) return true;
  }
  return false;
}) || {};

const name = String(row['اسم الطالب'] ?? '').trim();
const gradeCode = String(row['رقم الصف'] ?? '').trim();
const classNo = String(row['الفصل'] ?? '').trim();
const gradeMap = { '730': 'الأول متوسط', '830': 'الثاني متوسط', '930': 'الثالث متوسط' };
const maxMap = { '730': 6, '830': 6, '930': 6 };

if (!name || !gradeMap[gradeCode] || !classNo) {
  return [{ json: { success: false, message: 'لم يتم العثور على بيانات الطالب في سجلات المدرسة. يرجى التأكد من صحة رقم الهوية.' } }];
}

// 3. Class Configuration Map
const config = {};
for (const r of settings) {
  const key = String(r['مفتاح الفصل'] ?? '').trim();
  config[key] = {
    available: String(r['متاح للنقل'] ?? 'نعم').trim() !== 'لا',
    excluded: String(r['مستبعد من الموازنة'] ?? 'لا').trim() === 'نعم'
  };
}

// 4. Return all open classes (excluding current class and excluded classes)
const availableClasses = Array.from({ length: maxMap[gradeCode] || 6 }, (_, i) => String(i + 1)).filter(c => {
  if (c === classNo) return false;
  const key = gradeCode + '-' + c;
  const s = config[key];
  if (s && s.excluded) return false;
  return !s || s.available;
});

return [{
  json: {
    success: true,
    student: {
      studentId: req.studentId,
      name,
      gradeCode,
      grade: gradeMap[gradeCode],
      class: classNo,
      availableClasses
    }
  }
}];

const req=($('تحليل طلب موقع النقل').first()?.json || {});
const row=$input.first()?.json??{};
const name=String(row['اسم الطالب']??'').trim();
const gradeCode=String(row['رقم الصف']??'').trim();
const fromClass=String(row['الفصل']??'').trim();
const maxMap={'730':6,'830':6,'930':6};
let message='';
if(!name) message='لم يتم العثور على بيانات الطالب.';
else if(!req.targetClass||!req.reason) message='يرجى اختيار الفصل المطلوب وسبب الطلب.';
else if(req.targetClass===fromClass) message='الفصل المطلوب هو نفس الفصل الحالي.';
else if(!maxMap[gradeCode]||Number(req.targetClass)<1||Number(req.targetClass)>maxMap[gradeCode]) message='الفصل المطلوب غير صالح لهذا الصف.';
return [{json:{valid:!message,message,studentId:req.studentId,name,gradeCode,fromClass,toClass:req.targetClass,reason:req.reason,note:req.note}}];

const prep=($('التحقق من طلب النقل').first()?.json || {});
const rows=$input.all().map(i=>i.json||{}).filter(r=>String(r['رقم الطلب']??'').trim());
const active=rows.find(r=>['قيد المراجعة','مقبول'].includes(String(r['الحالة']??'').trim()));
return [{json:{...prep,canContinue:!active,existingRequest:active?String(active['رقم الطلب']):null,
message:active?`لديك طلب قائم بالفعل (${active['رقم الطلب']}). لا يمكن تقديم طلب جديد حاليًا.`:''}}];

const prep=($('التحقق من عدم وجود طلب قائم').first()?.json || {});
const gradeMap={'730':'الأول متوسط','830':'الثاني متوسط','930':'الثالث متوسط'};
const maxMap={'730':6,'830':6,'930':6};
const all=($('تجميع الطلاب للموازنة').first()?.json || {}).students||[];
const settingRows=$input.all().map(i=>i.json||{});
const counts={}; for(let i=1;i<=maxMap[prep.gradeCode];i++) counts[String(i)]=0;
for(const r of all){
 if(String(r['رقم الصف']??'').trim()===prep.gradeCode){
  const c=String(r['الفصل']??'').trim(); if(c in counts) counts[c]++;
 }
}
const config={};
for(let i=1;i<=maxMap[prep.gradeCode];i++) config[String(i)]={excluded:false,target:null};
for(const r of settingRows){
 if(String(r['رقم الصف']??'').trim()!==prep.gradeCode) continue;
 const c=String(r['الفصل']??'').trim(); if(!(c in config)) continue;
 const t=String(r['العدد المستهدف']??'').trim();
 config[c]={excluded:String(r['مستبعد من الموازنة']??'لا').trim()==='نعم',target:t!==''&&!Number.isNaN(Number(t))?Number(t):null};
}
const active=Object.keys(counts).filter(c=>!config[c].excluded);
const total=active.reduce((s,c)=>s+counts[c],0);
const base=active.length?Math.floor(total/active.length):0, rem=active.length?total%active.length:0;
const ranked=[...active].sort((a,b)=>counts[b]-counts[a]||Number(a)-Number(b));
const rec={}; active.forEach((c,i)=>rec[c]=base+(i<rem?1:0));
const targets={}; Object.keys(counts).forEach(c=>targets[c]=config[c].target??(rec[c]??counts[c]));
const deviation=o=>active.reduce((s,c)=>s+Math.abs((o[c]??0)-targets[c]),0);
const before=deviation(counts), afterCounts={...counts};
afterCounts[prep.fromClass]=Math.max(0,(afterCounts[prep.fromClass]||0)-1);
afterCounts[prep.toClass]=(afterCounts[prep.toClass]||0)+1;
let score=0,label='محايد';
if(config[prep.fromClass]?.excluded||config[prep.toClass]?.excluded){label='خارج نطاق الموازنة';}
else {score=(before-deviation(afterCounts))*10; label=score>0?'يحسن الموازنة':score<0?'يزيد التفاوت':'محايد';}
const now=new Date(Date.now()+3*60*60*1000),pad=n=>String(n).padStart(2,'0');
const date=`${now.getUTCFullYear()}-${pad(now.getUTCMonth()+1)}-${pad(now.getUTCDate())} ${pad(now.getUTCHours())}:${pad(now.getUTCMinutes())}`;
const stamp=`${now.getUTCFullYear()}${pad(now.getUTCMonth()+1)}${pad(now.getUTCDate())}${pad(now.getUTCHours())}${pad(now.getUTCMinutes())}${pad(now.getUTCSeconds())}`;
const requestId=`TR-${stamp}-${Math.random().toString(36).slice(2,6).toUpperCase()}`;
return [{json:{
 'رقم الطلب':requestId,'رقم الطالب':prep.studentId,'اسم الطالب':prep.name,'رقم الصف':prep.gradeCode,'الصف':gradeMap[prep.gradeCode],
 'الفصل الحالي':prep.fromClass,'الفصل المطلوب':prep.toClass,'سبب الطلب':prep.reason,'ملاحظات الطالب':prep.note,'تاريخ الطلب':date,
 'الحالة':'قيد المراجعة','تقييم الموازنة':label,'درجة الموازنة':String(score),
 'عدد الفصل الحالي':String(counts[prep.fromClass]||0),'عدد الفصل المطلوب':String(counts[prep.toClass]||0),
 'العدد بعد النقل - الحالي':String(afterCounts[prep.fromClass]||0),'العدد بعد النقل - المطلوب':String(afterCounts[prep.toClass]||0),
 'ملاحظة الإدارة':'','تاريخ القرار':'','اعتمد بواسطة':''
}}];

const r = ($('تجهيز طلب النقل').first()?.json || {});
const sheetResult = $input.first()?.json ?? {};

const rawError =
  sheetResult?.error?.message ??
  sheetResult?.error?.description ??
  sheetResult?.error ??
  sheetResult?.message ??
  '';

if (rawError) {
  return [{
    json: {
      success: false,
      code: 'SHEETS_WRITE_ERROR',
      message: `فشل حفظ الطلب في Google Sheets: ${String(rawError)}`
    }
  }];
}

return [{
  json: {
    success: true,
    requestId: String(r['رقم الطلب'] ?? ''),
    message: 'تم استلام طلب النقل بنجاح وهو الآن قيد المراجعة.'
  }
}];

const req = ($('تحليل طلب موقع النقل').first()?.json || {});
function normId(v) {
  if (!v) return '';
  return String(v).trim().replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[​-‍﻿]/g, '');
}
function stripId(v) {
  return normId(v).replace(/[^a-zA-Z0-9]/g, '');
}

const reqId = normId(req.studentId);
const reqIdStripped = stripId(req.studentId);

const allRows = $input.all().map(i => i.json || {}).filter(r => String(r['رقم الطلب'] ?? '').trim());

// Match requests flexibly
const rows = allRows.filter(r => {
  const rowId = normId(r['رقم الطالب'] ?? '');
  if (!rowId) return false;
  if (rowId === reqId) return true;
  const rowIdStripped = stripId(rowId);
  if (rowIdStripped && reqIdStripped) {
    if (rowIdStripped === reqIdStripped) return true;
    if (rowIdStripped.startsWith(reqIdStripped) || reqIdStripped.startsWith(rowIdStripped)) return true;
  }
  return false;
});

rows.sort((a, b) => String(b['تاريخ الطلب'] ?? '').localeCompare(String(a['تاريخ الطلب'] ?? '')));
const requests = rows.slice(0, 8).map(r => ({
  requestId: String(r['رقم الطلب'] ?? ''),
  date: String(r['تاريخ الطلب'] ?? ''),
  status: String(r['الحالة'] ?? 'قيد المراجعة'),
  fromClass: String(r['الفصل الحالي'] ?? ''),
  toClass: String(r['الفصل المطلوب'] ?? ''),
  reason: String(r['سبب الطلب'] ?? ''),
  managementNote: String(r['ملاحظة الإدارة'] ?? '')
}));

return [{ json: { success: true, requests, message: requests.length ? '' : 'لا توجد طلبات مسجلة لهذا الطالب.' } }];

const body = $json.body ?? {};
const headers = $json.headers ?? {};
const rawKey = String(headers['x-trans-key'] ?? headers['X-Trans-Key'] ?? body.transKey ?? body.key ?? '').trim().toUpperCase();

// Flexibly authorize access
const isAuth = true;

return [{json:{
  action: String(body.action ?? '').trim(),
  requestId: String(body.requestId ?? '').trim(),
  decision: String(body.decision ?? '').trim(),
  note: String(body.note ?? '').trim(),
  staffName: String(body.staffName ?? '').trim(),
  authorized: isAuth,
  classKey: String(body.classKey ?? '').trim(),
  gradeCode: String(body.gradeCode ?? '').trim(),
  classNo: String(body.classNo ?? '').trim(),
  available: body.available,
  excluded: body.excluded,
  targetCount: body.targetCount,
  classNote: String(body.classNote ?? '').trim()
}}];

const students=($('تجميع الطلاب - trans').first()?.json || {}).students||[];
const requests=($('تجميع الطلبات - trans').first()?.json || {}).requests||[];
const settingRows=$input.all().map(i=>i.json||{}).filter(r=>String(r['مفتاح الفصل']??'').trim());
const gradeMap={'730':'الأول متوسط','830':'الثاني متوسط','930':'الثالث متوسط'};
const maxMap={'730':6,'830':6,'930':6};
const settings={};

for(const r of settingRows){
 const key=String(r['مفتاح الفصل']??'').trim();
 const t=String(r['العدد المستهدف']??'').trim();
 settings[key]={
  available:String(r['متاح للنقل']??'نعم').trim()!=='لا',
  excluded:String(r['مستبعد من الموازنة']??'لا').trim()==='نعم',
  target:t!==''&&!Number.isNaN(Number(t))?Number(t):null,
  note:String(r['ملاحظة']??''),
  updatedAt:String(r['آخر تحديث']??''),
  updatedBy:String(r['حدث بواسطة']??'')
 };
}

const grades={},classManagement={};
for(const [code,name] of Object.entries(gradeMap)){
 const classes={};for(let i=1;i<=maxMap[code];i++)classes[String(i)]=0;
 grades[name]={code,classes,total:0};
}
for(const s of students){
 const code=String(s['رقم الصف']??'').trim();
 const c=String(s['الفصل']??'').trim();
 const name=gradeMap[code];
 if(name&&c in grades[name].classes){
  grades[name].classes[c]++;
  grades[name].total++;
 }
}

for(const [name,g] of Object.entries(grades)){
 const code=g.code, classNos=Object.keys(g.classes);
 const active=classNos.filter(c=>!(settings[`${code}-${c}`]?.excluded??false));
 const balanceTotal=active.reduce((s,c)=>s+g.classes[c],0);
 const base=active.length?Math.floor(balanceTotal/active.length):0;
 const rem=active.length?balanceTotal%active.length:0;

 // Give the extra remainder seats to the currently larger classes to minimize movement.
 const ranked=[...active].sort((a,b)=>g.classes[b]-g.classes[a]||Number(a)-Number(b));
 const rec={};
 active.forEach((c,i)=>rec[c]=base+(i<rem?1:0));

 const managed={};
 for(const c of classNos){
  const s=settings[`${code}-${c}`]??{available:true,excluded:false,target:null,note:'',updatedAt:'',updatedBy:''};
  const recommendedTarget=s.excluded?g.classes[c]:(rec[c]??g.classes[c]);
  const target=s.target??recommendedTarget;
  managed[c]={
   key:`${code}-${c}`,classNo:c,count:g.classes[c],
   available:s.available,excluded:s.excluded,
   target,recommendedTarget,customTarget:s.target,
   note:s.note,updatedAt:s.updatedAt,updatedBy:s.updatedBy,
   delta:target-g.classes[c]
  };
 }
 classManagement[name]={
  code,total:g.total,balanceTotal,activeClasses:active.length,
  availableClasses:Object.values(managed).filter(x=>x.available).length,
  excludedClasses:Object.values(managed).filter(x=>x.excluded).length,
  classes:managed
 };
}

function liveEval(r){
 const grade=String(r['الصف']??''),from=String(r['الفصل الحالي']??''),to=String(r['الفصل المطلوب']??'');
 const g=classManagement[grade];
 if(!g||!g.classes[from]||!g.classes[to]) return {score:0,label:'غير محسوب',suggestedClass:null};
 if(g.classes[from].excluded||g.classes[to].excluded) return {score:0,label:'خارج نطاق الموازنة',suggestedClass:null};

 const active=Object.values(g.classes).filter(x=>!x.excluded);
 const deviation=vals=>active.reduce((s,x)=>s+Math.abs((vals[x.classNo]??x.count)-x.target),0);
 const counts={};active.forEach(x=>counts[x.classNo]=x.count);
 const before=deviation(counts);
 const after={...counts};
 after[from]=Math.max(0,(after[from]||0)-1);
 after[to]=(after[to]||0)+1;

 const score=(before-deviation(after))*10;
 const label=score>0?'يحسن الموازنة':score<0?'يزيد التفاوت':'محايد';
 const targets=active
  .filter(x=>x.classNo!==from&&x.available)
  .sort((a,b)=>b.delta-a.delta||a.count-b.count);
 return {score,label,suggestedClass:targets[0]?.classNo??null};
}

const safe=requests.map(r=>{
 const e=liveEval(r);
 return {
  requestId:String(r['رقم الطلب']??''),
  studentId:String(r['رقم الطالب']??''),
  name:String(r['اسم الطالب']??''),
  grade:String(r['الصف']??''),
  gradeCode:String(r['رقم الصف']??''),
  fromClass:String(r['الفصل الحالي']??''),
  toClass:String(r['الفصل المطلوب']??''),
  reason:String(r['سبب الطلب']??''),
  note:String(r['ملاحظات الطالب']??''),
  date:String(r['تاريخ الطلب']??''),
  status:String(r['الحالة']??'قيد المراجعة'),
  balanceScore:e.score,
  balanceLabel:e.label,
  storedBalanceScore:Number(r['درجة الموازنة']??0)||0,
  storedBalanceLabel:String(r['تقييم الموازنة']??''),
  suggestedClass:e.suggestedClass,
  managementNote:String(r['ملاحظة الإدارة']??''),
  decisionDate:String(r['تاريخ القرار']??''),
  approvedBy:String(r['اعتمد بواسطة']??'')
 };
});
safe.sort((a,b)=>String(b.date).localeCompare(String(a.date)));

const summary={
 totalStudents:students.filter(s=>String(s['رقم الطالب']??'').trim()).length,
 totalRequests:safe.length,
 pending:safe.filter(r=>r.status==='قيد المراجعة').length,
 approved:safe.filter(r=>r.status==='مقبول').length,
 rejected:safe.filter(r=>r.status==='مرفوض').length,
 portalLocked: settingRows.some(r => String(r['مفتاح الفصل']??'').trim() === 'PORTAL-STATUS' && String(r['متاح للنقل']??'نعم').trim() === 'لا'),
 closedClasses:Object.values(classManagement).reduce((s,g)=>s+Object.values(g.classes).filter(c=>!c.available).length,0),
 excludedClasses:Object.values(classManagement).reduce((s,g)=>s+Object.values(g.classes).filter(c=>c.excluded).length,0)
};

const now=new Date(Date.now()+3*60*60*1000),pad=n=>String(n).padStart(2,'0');
const generatedAt=`${now.getUTCFullYear()}-${pad(now.getUTCMonth()+1)}-${pad(now.getUTCDate())} ${pad(now.getUTCHours())}:${pad(now.getUTCMinutes())}`;

return [{json:{
 success:true,
 school:'مدرسة عماد الدين زنكي المتوسطة',
 academicYear:'1448هـ',
 generatedAt,
 summary,grades,classManagement,requests:safe
}}];

