 fromClass:String(row['الفصل الحالي']??''),toClass:String(row['الفصل المطلوب']??''),note:req.note,staffName:req.staffName,decisionDate,
 newStatus:decision==='approve'?'مقبول':'مرفوض'
}}];

const d=($('تجهيز قرار trans').first()?.json || {});
const row=$input.first()?.json??{};
const name=String(row['اسم الطالب']??'').trim();
const current=String(row['الفصل']??'').trim();
if(!name) return [{json:{canApprove:false,message:'لم يتم العثور على الطالب في بيانات الطلاب.'}}];
if(current!==d.fromClass) return [{json:{canApprove:false,message:`تعذر الاعتماد لأن فصل الطالب تغيّر من ${d.fromClass} إلى ${current}. حدّث اللوحة وراجع الطلب.`}}];
return [{json:{canApprove:true,studentId:d.studentId,toClass:d.toClass}}];

const prep = ($('التحقق من طلب النقل').first()?.json || {});
const row = $input.first()?.json ?? {};
const found = String(row['مفتاح الفصل'] ?? '').trim();
